<?php
namespace App\Http\Controllers;
use App\Models\ExpenseAdvance;
use App\Models\Expense;
use App\Models\ExpenseCategory;
use App\Services\FundsLedger;
use Illuminate\Http\Request;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class ExpenseAdvanceController extends Controller {
 public function index(Request $request){abort_unless($request->user()->hasPermission('expenses'),403);if(!\Illuminate\Support\Facades\Schema::hasTable('expense_advances')||!\Illuminate\Support\Facades\Schema::hasColumn('expenses','expense_advance_id'))return response()->view('expense-advances.setup',[],503);$data=$request->validate(['month'=>['nullable','date_format:Y-m']]);$month=Carbon::createFromFormat('!Y-m',$data['month']??$request->session()->get('expense_advances_month',now('Asia/Karachi')->format('Y-m')))->startOfMonth();$request->session()->put('expense_advances_month',$month->format('Y-m'));$advances=ExpenseAdvance::whereDate('advance_date','>=',$month->toDateString())->whereDate('advance_date','<=',$month->copy()->endOfMonth()->toDateString())->orderBy('advance_date')->orderBy('id')->get();$settlements=Expense::whereNotNull('expense_advance_id')->orderBy('expense_date')->get()->groupBy('expense_advance_id');$categories=ExpenseCategory::where('status',true)->with('activeSubCategories')->orderBy('name')->get();$categoryOptions=$categories->mapWithKeys(fn($c)=>[$c->id=>$c->activeSubCategories->map(fn($sub)=>['id'=>$sub->id,'name'=>$sub->name])->values()]);return view('expense-advances.index',compact('month','advances','settlements','categories','categoryOptions'));}
 public function store(Request $request){abort_unless($request->user()->hasPermission('expenses'),403);$data=$request->validate(['recipient_name'=>['required','string','max:255'],'month'=>['required','date_format:Y-m'],'entries'=>['required','array','min:1','max:100'],'entries.*.week'=>['required','integer','between:1,5'],'entries.*.advance_date'=>['required','date_format:Y-m-d','before_or_equal:'.now('Asia/Karachi')->toDateString()],'entries.*.amount'=>['required','regex:/^\d{1,11}(\.\d{1,2})?$/','numeric','min:0.01'],'entries.*.purpose'=>['nullable','string','max:1000'],'entries.*.submission_key'=>['required','uuid','distinct']]);foreach($data['entries'] as $r){$date=Carbon::parse($r['advance_date']);if($date->format('Y-m')!==$data['month']||intdiv($date->day-1,7)+1!=(int)$r['week'])throw ValidationException::withMessages(['entries'=>'Actual payment date must match the selected month and week.']);}DB::transaction(function()use($data,$request){DB::table('users')->where('id',$request->user()->id)->lockForUpdate()->first();foreach($data['entries'] as $r){$existing=ExpenseAdvance::where('submission_key',$r['submission_key'])->first();if($existing){if($existing->recipient_name!==$data['recipient_name']||$existing->advance_date->toDateString()!==$r['advance_date']||FundsLedger::paise((string)$existing->amount)!==FundsLedger::paise((string)$r['amount'])||($existing->purpose??'')!==($r['purpose']??''))throw ValidationException::withMessages(['entries'=>'Saved entry changed. Reload before correcting it.']);continue;}unset($r['week']);ExpenseAdvance::create($r+['recipient_name'=>$data['recipient_name'],'created_by'=>$request->user()->id]);}});return redirect()->route('expense-advances.index',['month'=>$data['month']])->with('success','Weekly advances saved. Funds cash deducted once.');}
 public function settle(Request $request,ExpenseAdvance $advance){abort_unless($request->user()->hasPermission('expenses'),403);$data=$request->validate(['expense_date'=>['required','date_format:Y-m-d','before_or_equal:'.now('Asia/Karachi')->toDateString()],'expense_category_id'=>['required','integer','exists:expense_categories,id'],'expense_sub_category_id'=>['nullable','integer','exists:expense_sub_categories,id'],'amount'=>['required','regex:/^\d{1,11}(\.\d{1,2})?$/','numeric','min:0.01'],'description'=>['required','string','max:5000'],'version'=>['required','string']]);DB::transaction(function()use($advance,$data){$row=ExpenseAdvance::whereKey($advance->id)->lockForUpdate()->firstOrFail();$used=Expense::where('expense_advance_id',$row->id)->get();$version=hash('sha256',json_encode([$row->getAttributes(),$used->map->getAttributes()->all()]));if(!hash_equals($version,$data['version']))throw ValidationException::withMessages(['amount'=>'Settlement changed. Reload before saving.']);$remaining=FundsLedger::paise((string)$row->amount)-$used->sum(fn($e)=>FundsLedger::paise((string)$e->amount));if(FundsLedger::paise((string)$data['amount'])>$remaining)throw ValidationException::withMessages(['amount'=>'Bill exceeds unused advance. Record any extra cash separately as a normal expense.']);if($data['expense_date']<$row->advance_date->toDateString())throw ValidationException::withMessages(['expense_date'=>'Bill date cannot precede advance payment.']);$category=ExpenseCategory::where('status',true)->with('activeSubCategories')->findOrFail($data['expense_category_id']);$sub=$data['expense_sub_category_id']??null;if($category->activeSubCategories->isNotEmpty()&&!$category->activeSubCategories->contains('id',(int)$sub))throw ValidationException::withMessages(['expense_sub_category_id'=>'Select a subcategory belonging to this category.']);if($category->activeSubCategories->isEmpty())$sub=null;Expense::create(['expense_no'=>'EAS-'.(string)\Illuminate\Support\Str::uuid(),'expense_date'=>$data['expense_date'],'expense_category_id'=>$category->id,'expense_sub_category_id'=>$sub,'category'=>$category->name,'expense_advance_id'=>$row->id,'amount'=>$data['amount'],'vendor_name'=>$row->recipient_name,'paid_by'=>$row->recipient_name,'payment_method'=>'cash','description'=>$data['description']]);});return back()->with('success','Bill settled against advance. No second cash deduction.');}
 public function destroy(Request $request,ExpenseAdvance $advance){abort_unless($request->user()->hasPermission('expenses'),403);$request->validate(['version'=>['required','string']]);DB::transaction(function()use($advance,$request){$row=ExpenseAdvance::whereKey($advance->id)->lockForUpdate()->firstOrFail();if(!hash_equals(hash('sha256',json_encode($row->getAttributes())),$request->input('version')))throw ValidationException::withMessages(['advance'=>'Record changed; reload.']);if(Expense::where('expense_advance_id',$row->id)->exists())throw ValidationException::withMessages(['advance'=>'Settled advance cannot be deleted.']);$row->delete();});return back()->with('success','Mistaken advance removed. Funds recalculated.');}
}
